import './style.css';
import './milestone.css';
import './analytics.css';
import './forecast.css';
import './insights.css';
import './scenario.css';
import './integrations.css';
import './settings.css';
import './reports.css';
import './models.css';
import './application.css';
import './layout-fixes.css';
import './import.css';
import './readability.css';
import { resolveApiBase } from './api-base.js';
import { apiRequest } from './api-client.js';
import { ImportWorkflow } from './import-workflow.js';

const API=resolveApiBase({mode:import.meta.env.MODE,viteApiUrl:import.meta.env.VITE_API_URL,isTauri:Boolean(window.__TAURI__||window.__TAURI_INTERNALS__)});
const state={page:location.hash.slice(1)||'overview',days:+localStorage.getItem('ts-days')||30,filters:JSON.parse(localStorage.getItem('ts-filters')||'{}'),data:null,options:{},application:null,loading:true,error:null,startup:null,keepRunningInTray:false,group:'application',forecastMetric:'total_tokens',forecastHorizon:30,wizardStep:1,wizardChoice:'demo',telemetryReset:{open:false,running:false,message:''}};let liveSource;
const money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:4}),num=new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1});
let backendToken='';
const api=(path,options={})=>apiRequest(API,path,{...options,headers:{...(options.headers||{}),...(backendToken?{'X-TokenScope-Key':backendToken}:{})}});
const desktopInvoke=window.__TAURI__?.core?.invoke||window.__TAURI_INTERNALS__?.invoke;
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
async function checkDesktopStartup(){if(!desktopInvoke){load();return}try{const snapshot=await desktopInvoke('startup_status');state.startup=snapshot;if(snapshot.status==='HEALTHY'){backendToken=await desktopInvoke('backend_auth_token')||'';state.startup=null;loadAfterDesktopStartup();return}state.loading=snapshot.status==='STARTING';render();if(snapshot.status==='STARTING')setTimeout(checkDesktopStartup,400)}catch(error){state.loading=false;state.startup={status:'FAILED',failure:{category:'STARTUP_STATE_UNAVAILABLE',summary:'The desktop startup state could not be read.',health_check:String(error),application_version:'0.15.0'}};render()}}
async function loadAfterDesktopStartup(attempt=0){await load();if(state.error&&attempt<20){state.error=null;state.loading=true;render();setTimeout(()=>loadAfterDesktopStartup(attempt+1),500)}}
function query(extra={}){const q=new URLSearchParams({days:state.days,...Object.fromEntries(Object.entries(state.filters).filter(([,v])=>v)),...extra});return q.toString()}
async function load(){state.loading=true;render();try{state.application=await api('/application');if(!state.application.first_run_complete){state.error=null;state.loading=false;render();return}state.options=await api('/filters');state.data=state.page==='overview'?await api('/overview?'+query()):state.page==='usage'||state.page==='costs'?await api('/analytics?'+query({group_by:state.group})):state.page==='pricing'?await api('/pricing'):state.page==='models'?await api('/models/inventory?days='+state.days):state.page==='forecasts'?await api('/forecasts?'+query({metric:state.forecastMetric,horizon:state.forecastHorizon,training_days:180})):state.page==='optimization'?await api('/optimization?days='+state.days):state.page==='anomalies'?await api('/anomalies?days=90'):state.page==='budgets'?await api('/budgets'):state.page==='integrations'?await api('/integrations'):state.page==='reports'?await Promise.all([api('/reports/executive?days='+state.days),api('/efficiency?days='+state.days)]).then(([report,efficiency])=>({report,efficiency})):state.page==='settings'?await Promise.all([api('/cloud-providers'),api('/security/status'),api('/settings/retention'),api('/audit?limit=20'),api('/settings/privacy'),api('/health')]).then(([cloud,security,retention,audit,privacy,health])=>({cloud,security,retention,audit,privacy,health})):null;if(state.page==='settings'&&desktopInvoke)state.keepRunningInTray=await desktopInvoke('get_keep_running_in_tray');state.error=null}catch(e){state.error=e.message}state.loading=false;render()}
const labels={overview:'Overview',usage:'Usage',costs:'Costs',models:'Models',forecasts:'Forecasts',optimization:'Optimization',anomalies:'Anomalies',budgets:'Budgets',scenario:'Scenario Lab',reports:'Reports',integrations:'Integrations',settings:'Settings',import:'Import Data',pricing:'Pricing'};
function shell(content){const mode=state.application?.mode||'Operations',demo=state.data?.is_demo;return `<div class="shell mode-${mode.toLowerCase()}"><aside><div class="brand"><span class="logo">AI</span><div><strong>AI Optimization Tool</strong><small>LOCAL-FIRST INTELLIGENCE</small></div></div><div class="mode-switch" aria-label="Application view">${['Executive','Operations','Engineering'].map(x=>`<button data-mode="${x}" class="${mode===x?'on':''}">${x}</button>`).join('')}</div><nav>${Object.entries(labels).map(([id,label])=>`<a href="#${id}" data-page="${id}" class="${state.page===id?'active':''}"><i>${state.page===id?'●':'○'}</i>${label}</a>`).join('')}</nav><div class="side-bottom"><div class="collector"><span class="pulse"></span><div><strong id="live-rpm">0 requests/min</strong><small id="live-tpm">LIVE LOCAL WINDOW</small></div></div></div></aside><main>${demo?'<div class="demo-banner"><strong>DEMO DATA</strong><span>Sample telemetry is active.</span><button id="remove-demo">Remove demo data</button></div>':''}${content}<footer><span>Privacy mode active — content and identity disabled.</span><span>${state.application?.name||'AI Optimization Tool'} · v${state.application?.version||'0.10.0'}</span></footer></main></div><div class="modal-backdrop hidden" id="command-modal"><section class="panel command-modal"><p class="eyebrow">COMMAND PALETTE</p><input id="command-search" placeholder="Search applications, models, teams, budgets…"><div id="command-results">${Object.entries(labels).map(([id,label])=>`<button data-command-page="${id}">Go to ${label}<kbd>${label[0]}</kbd></button>`).join('')}</div><small>Press Escape to close · Ctrl+K to open</small></section></div>`}
function header(title,subtitle){return `<header><div><h1>${title}</h1><p>${subtitle}</p></div><div class="header-actions"><button id="global-search">⌕ Search <kbd>Ctrl K</kbd></button><span class="live"><i></i> LIVE</span><button id="refresh">↻ Refresh</button></div></header>`}
function filterbar(){return `<div class="filterbar"><div class="segmented">${[7,30,90].map(d=>`<button data-days="${d}" class="${state.days===d?'on':''}">${d}D</button>`).join('')}</div>${['provider','model','department','application'].map(key=>`<label><span>${key}</span><select data-filter="${key}"><option value="">All</option>${(state.options[key]||[]).map(v=>`<option ${state.filters[key]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<button id="clear-filters">Clear filters</button></div>`}
function dataBadge(kind){const normalized=kind.toUpperCase().startsWith('FORECAST')?'FORECAST':kind.toUpperCase().startsWith('ESTIMAT')?'ESTIMATED':'OBSERVED';return `<span class="data-badge ${normalized.toLowerCase()}" title="${normalized==='OBSERVED'?'Actual local telemetry':normalized==='ESTIMATED'?'Calculated from stated assumptions or pricing':'Statistical future projection'}">${normalized}</span>`}
function metric(label,value,status='Observed'){return `<article class="metric"><div class="metric-top"><p>${label}</p><span title="Calculated from filtered local telemetry">ⓘ</span></div><h3>${value}</h3><p class="trend good">${dataBadge(status)} <span>· selected period</span></p></article>`}
function bars(items,nameKey,valueKey,format=num.format){const max=Math.max(...items.map(x=>x[valueKey]),1);return items.slice(0,7).map(x=>`<div class="bar-row"><span><b>${x[nameKey]}</b><small>${num.format(x.requests||0)} requests</small></span><i><em style="width:${x[valueKey]/max*100}%"></em></i><strong>${format(x[valueKey])}</strong></div>`).join('')||'<div class="empty-inline">No records match these filters.</div>'}
function graph(series){if(!series.length)return'<div class="empty-inline">Generate demo data or import telemetry to begin.</div>';const vals=series.map(x=>x.tokens),max=Math.max(...vals),min=Math.min(...vals),w=700,h=170,pts=vals.map((v,i)=>`${i?'L':'M'} ${i/(vals.length-1||1)*w} ${h-(v-min)/(max-min||1)*h}`).join(' ');return `<div class="api-chart"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path d="${pts} L${w} ${h} L0 ${h}Z" fill="#70e3b422"/><path d="${pts}" fill="none" stroke="#70e3b4" stroke-width="2" vector-effect="non-scaling-stroke"/></svg></div><div class="chart-foot"><span>${series[0].date}</span><span>Observed</span><span>${series.at(-1).date}</span></div>`}
function overview(d){if(d.is_empty)return onboarding();const t=d.totals,mode=state.application?.mode||'Operations';const metrics=mode==='Executive'?metric('AI SPEND',money.format(t.spend),'Estimated')+metric('BUDGET RISK',t.spend>4?'HIGH':'LOW','Estimated')+metric('AI EFFICIENCY',t.success_rate+'%','Estimated')+metric('TOP APPLICATIONS',d.applications.length):mode==='Engineering'?metric('REQUESTS',num.format(t.requests))+metric('TOTAL TOKENS',num.format(t.tokens))+metric('SUCCESS RATE',t.success_rate+'%')+metric('AVG LATENCY',Math.round(t.average_latency_ms)+' ms'):metric('TOTAL TOKENS',num.format(t.tokens))+metric('AI SPEND',money.format(t.spend),'Estimated')+metric('REQUESTS',num.format(t.requests))+metric('SUCCESS RATE',t.success_rate+'%')+metric('AVG LATENCY',Math.round(t.average_latency_ms)+' ms');return shell(`${header(`${mode} Overview`,mode==='Executive'?'Financial impact and optimization priorities.':mode==='Engineering'?'Detailed provider and request behavior from permitted metadata.':'Observed usage, service health, and estimated costs.')}${filterbar()}<section class="metrics ${mode==='Executive'?'four':''}">${metrics}</section><section class="grid-main"><article class="panel chart-panel"><div class="panel-head"><div><p class="eyebrow">${mode==='Executive'?'AI SPEND TREND':'TOKEN USAGE'}</p><h2>Historical activity</h2></div>${dataBadge('Observed')}</div>${graph(d.timeseries)}</article><article class="panel"><p class="eyebrow">${mode==='Executive'?'TOP APPLICATIONS':'SPEND BY MODEL'}</p><h2>${mode==='Executive'?'Largest consumers':'Cost distribution'}</h2>${mode==='Executive'?bars(d.applications,'application','spend',money.format):bars(d.models,'model','spend',money.format)}</article></section><section class="lower-grid"><article class="panel"><p class="eyebrow">MODEL DISTRIBUTION</p><h2>${mode==='Engineering'?'Provider / model behavior':'Tokens by model'}</h2>${bars(d.models,'model','tokens')}</article><article class="panel"><p class="eyebrow">APPLICATION USAGE</p><h2>Largest consumers</h2>${bars(d.applications,'application','tokens')}</article></section>`) }
function analyticsPage(d,cost=false){const totals=d.items.reduce((a,x)=>({requests:a.requests+x.requests,tokens:a.tokens+x.total_tokens,spend:a.spend+x.total_spend,failed:a.failed+x.failed_requests,cached:a.cached+x.cached_tokens}),{requests:0,tokens:0,spend:0,failed:0,cached:0});return shell(`${header(cost?'Cost analytics':'Usage analytics',cost?'Understand estimated AI spend by every organizational dimension.':'Drill into locally observed token and request activity.')}${filterbar()}<div class="groupbar"><span>GROUP BY</span>${['provider','model','department','team','application','workload','day','hour'].map(x=>`<button data-group="${x}" class="${state.group===x?'on':''}">${x}</button>`).join('')}</div><section class="metrics four">${metric('REQUESTS',num.format(totals.requests))}${metric('TOTAL TOKENS',num.format(totals.tokens))}${metric('FAILED REQUESTS',num.format(totals.failed))}${cost?metric('TOTAL SPEND',money.format(totals.spend),'Estimated'):metric('CACHED TOKENS',num.format(totals.cached))}</section><article class="panel data-panel"><div class="panel-head"><div><p class="eyebrow">ANALYTICAL BREAKDOWN</p><h2>${state.group[0].toUpperCase()+state.group.slice(1)} performance</h2></div><span class="tag">${d.items.length} GROUPS</span></div>${analyticsTable(d.items,cost)}</article>`) }
function analyticsTable(items,cost){return `<div class="analytics-table"><div class="analytics-row head"><span>GROUP</span><span>REQUESTS</span><span>SUCCESS</span><span>${cost?'TOTAL COST':'INPUT TOKENS'}</span><span>${cost?'COST / REQUEST':'OUTPUT TOKENS'}</span><span>${cost?'COST / SUCCESS':'TOTAL TOKENS'}</span></div>${items.map(x=>`<div class="analytics-row"><strong>${x.name}</strong><span>${num.format(x.requests)}</span><span>${((x.successful_requests/x.requests)*100||0).toFixed(1)}%</span><span>${cost?money.format(x.total_spend):num.format(x.input_tokens)}</span><span>${cost?money.format(x.cost_per_request):num.format(x.output_tokens)}</span><span>${cost?money.format(x.cost_per_successful_request):num.format(x.total_tokens)}</span></div>`).join('')}</div>`}
let importWorkflow;function importPage(){return shell(`${header('Import telemetry','Add local usage data for analysis, forecasting, and optimization.')}<section class="import-workflow"><article class="panel import-upload"><div class="upload-zone" id="upload-zone" data-dragover="false"><div class="zone-content"><svg class="upload-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg><h2>Import telemetry</h2><p class="zone-title">Drag a CSV or JSON file here, or browse files.</p><p class="zone-subtitle">CSV · JSON · Up to 500 MB · Processed locally</p><button class="primary" id="browse-file">Browse Files</button><input id="file-input" type="file" accept=".csv,.json,.jsonl" style="display:none"></div></div></article><article class="panel import-panel" id="analysis-panel" style="display:none"><div class="panel-head"><div><p class="eyebrow">FILE ANALYSIS</p><h2 id="analysis-filename">File</h2></div></div><div class="analysis-grid" id="analysis-grid"></div><div id="sample-preview" class="sample-preview"></div><div class="action-row"><button id="continue-to-mapping" class="primary">Continue</button><button id="start-over" class="secondary">Choose different file</button></div></article><article class="panel import-panel" id="mapping-panel" style="display:none"><div class="panel-head"><div><p class="eyebrow">COLUMN MAPPING</p><h2>Map columns to telemetry fields</h2></div></div><div class="mapping-table" id="mapping-table"></div><div class="mapping-options"><label><strong>Duplicate handling:</strong><select id="duplicate-handling"><option value="skip" selected>Skip duplicates</option><option value="replace">Replace duplicates</option><option value="fail">Fail on duplicates</option></select></label></div><div class="action-row"><button id="preview-import" class="primary">Preview data</button><button id="back-to-analysis" class="secondary">Back</button></div></article><article class="panel import-panel" id="preview-panel" style="display:none"><div class="panel-head"><div><p class="eyebrow">IMPORT PREVIEW</p><h2>Review rows before import</h2></div></div><div class="preview-summary" id="preview-summary"></div><div id="preview-rows"></div><div class="action-row"><button id="start-import" class="primary">Start import</button><button id="back-to-mapping" class="secondary">Back</button></div></article><article class="panel import-panel" id="progress-panel" style="display:none"><div class="panel-head"><div><p class="eyebrow">IMPORT PROGRESS</p><h2 id="progress-title">Importing...</h2></div></div><div class="progress-container"><div class="progress-bar"><div class="progress-fill" id="progress-fill" style="width: 0%"/></div><div class="progress-text"><span id="progress-percent">0%</span><span id="progress-fraction">0 / 0 rows</span></div></div><div class="progress-stats"><div><strong id="stat-valid">0</strong><small>Valid rows</small></div><div><strong id="stat-rejected">0</strong><small>Rejected</small></div><div><strong id="stat-rate">0</strong><small>rows/sec</small></div><div><strong id="stat-elapsed">0:00</strong><small>Elapsed</small></div></div><div id="progress-messages"/><button id="cancel-import" class="secondary">Cancel</button></article><article class="panel import-panel history-panel" id="history-panel"><div class="panel-head"><div><h2>Import history</h2><p>Recent files processed on this device.</p></div></div><div id="history-list" class="history-list"><div class="empty-inline">Loading import history…</div></div></article></section>`)}
function pricingPage(d){return shell(`${header('Pricing registry','Versioned local model prices and organization-specific overrides.')}<div class="notice">${d.notice} Registry version ${d.version}.</div><section class="pricing-layout"><article class="panel"><div class="panel-head"><div><p class="eyebrow">ACTIVE PRICES</p><h2>Per million tokens</h2></div><span class="tag">${d.prices.length} MODELS</span></div><div class="analytics-table price-table"><div class="analytics-row head"><span>MODEL</span><span>PROVIDER</span><span>INPUT</span><span>OUTPUT</span><span>CACHED</span><span>STATUS</span></div>${d.prices.map(p=>`<div class="analytics-row"><strong>${p.model_id}</strong><span>${p.provider}</span><span>${money.format(p.input_price_per_million)}</span><span>${money.format(p.output_price_per_million)}</span><span>${money.format(p.cached_input_price_per_million)}</span><span>${p.custom?'CUSTOM':'BUNDLED'}</span></div>`).join('')}</div></article><article class="panel price-form"><p class="eyebrow">CUSTOM OVERRIDE</p><h2>Add or replace a model price</h2><label>Model ID<input id="price-model" placeholder="private-model-v1"></label><label>Provider<input id="price-provider" placeholder="Internal"></label><div><label>Input / 1M<input id="price-input" type="number" min="0" step=".01"></label><label>Output / 1M<input id="price-output" type="number" min="0" step=".01"></label><label>Cached / 1M<input id="price-cached" type="number" min="0" step=".01"></label></div><button class="primary" id="save-price">Save override</button><p class="help">Overrides apply to future events. Historical costs remain reproducible.</p></article></section>`) }
function forecastControls(){return `<div class="forecast-controls"><label>FORECAST METRIC<select id="forecast-metric">${[['requests','Requests'],['input_tokens','Input tokens'],['output_tokens','Output tokens'],['total_tokens','Total tokens'],['spend','Spend']].map(([v,l])=>`<option value="${v}" ${state.forecastMetric===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="segmented">${[7,30,90,365].map(h=>`<button data-horizon="${h}" class="${state.forecastHorizon===h?'on':''}">${h===365?'12M':h+'D'}</button>`).join('')}</div><span class="forecast-notice">Statistical estimate · not a guarantee</span></div>`}
function formatForecast(value){return state.forecastMetric==='spend'?money.format(value):num.format(value)}
function forecastGraph(d){const history=d.history,forecast=d.forecast,all=[...history.map(x=>x.value),...forecast.flatMap(x=>[x.lower,x.upper])],max=Math.max(...all),min=Math.min(...all),w=760,h=240,split=history.length/(history.length+forecast.length-1)*w,point=(v,i)=>`${i/(history.length+forecast.length-1)*w},${h-(v-min)/(max-min||1)*h}`,historyPath=history.map((x,i)=>`${i?'L':'M'}${point(x.value,i)}`).join(' '),expected=forecast.map((x,i)=>`${i?'L':'M'}${point(x.expected,history.length+i)}`).join(' '),upper=forecast.map((x,i)=>point(x.upper,history.length+i)).join(' '),lower=[...forecast].reverse().map((x,i)=>point(x.lower,history.length+forecast.length-1-i)).join(' ');return `<div class="forecast-chart"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path d="M${upper} L${lower} Z" class="interval"/><path d="${historyPath}" class="history-line"/><path d="${expected}" class="forecast-line"/><line x1="${split}" x2="${split}" y1="0" y2="${h}" class="today-line"/></svg><span class="today-label" style="left:${split/w*100}%">FORECAST START</span></div><div class="forecast-legend"><span><i class="observed-dot"></i>Historical</span><span><i class="forecast-dot"></i>Expected</span><span><i class="interval-box"></i>95% prediction interval</span></div>`}
function forecastPage(d){return shell(`${header('Forecasts','Locally backtested statistical estimates with transparent uncertainty.')}${forecastControls()}${filterbar()}<section class="metrics four">${metric(`EXPECTED ${d.horizon_days}D`,formatForecast(d.summary.expected),'Forecast')}${metric('LOWER BOUND',formatForecast(d.summary.lower),'95% interval')}${metric('UPPER BOUND',formatForecast(d.summary.upper),'95% interval')}${metric('BACKTEST sMAPE',d.accuracy.value.toFixed(2)+'%','Estimated error')}</section><section class="forecast-layout"><article class="panel forecast-main"><div class="panel-head"><div><p class="eyebrow">HISTORICAL + FORECAST</p><h2>${d.metric.replaceAll('_',' ')} <span>${d.training.points} training observations</span></h2></div><span class="tag">${d.selected_model}</span></div>${forecastGraph(d)}</article><article class="panel drivers"><p class="eyebrow">WHAT IS DRIVING THIS FORECAST?</p><h2>Evidence trail</h2>${d.drivers.map(x=>`<div class="driver"><span>${x.kind.toUpperCase()}</span><strong>${x.label}</strong><p>${x.evidence}</p></div>`).join('')}</article></section><section class="lower-grid"><article class="panel"><p class="eyebrow">MODEL BACKTEST</p><h2>Candidate accuracy <span>lower sMAPE is better</span></h2><div class="backtests">${d.backtests.map((x,i)=>`<div><span>${x.model}${i===0?' <b>SELECTED</b>':''}</span><i><em style="width:${x.smape===null?0:Math.max(3,100-Math.min(100,x.smape))}%"></em></i><strong>${x.smape===null?'FAILED':x.smape.toFixed(2)+'%'}</strong></div>`).join('')}</div></article><article class="panel"><p class="eyebrow">FORECAST EVIDENCE</p><h2>Reproducibility</h2><dl class="evidence"><div><dt>Training period</dt><dd>${d.training.start} to ${d.training.end}</dd></div><div><dt>Selected model</dt><dd>${d.selected_model}</dd></div><div><dt>Error measure</dt><dd>sMAPE on held-out observations</dd></div><div><dt>Uncertainty</dt><dd>95% prediction interval</dd></div><div><dt>Forecast ID</dt><dd>${d.forecast_id.slice(0,8)}</dd></div></dl></article></section>`) }
function forecastEmpty(message){return shell(`${header('Forecasts','Locally backtested statistical estimates with transparent uncertainty.')}${forecastControls()}${filterbar()}<article class="panel forecast-empty"><span>HISTORY REQUIRED</span><h2>More historical data is needed for a reliable forecast.</h2><p>${message}</p><button data-page="import">Import historical telemetry</button></article>`) }
function optimizationPage(d){return shell(`${header('Optimization','Explainable savings opportunities generated locally from deterministic rules.')}<div class="notice">${d.method}</div><section class="metrics four">${metric('OPPORTUNITIES',d.summary.count,'Rule matches')}${metric('POTENTIAL SAVINGS',money.format(d.summary.estimated_monthly_savings),'Estimated monthly')}${metric('CONTENT REQUIRED','No','Privacy-safe')}${metric('LLM REQUIRED','No','Deterministic')}</section><section class="recommendation-list">${d.recommendations.map((x,i)=>`<article class="panel recommendation"><div class="rec-rank">${String(i+1).padStart(2,'0')}</div><div class="rec-content"><div class="rec-title"><span>${x.category}</span><h2>${x.title}</h2></div><p>${x.reason}</p><div class="evidence-box"><b>OBSERVED EVIDENCE</b>${x.evidence}</div><div class="action-box"><b>RECOMMENDED ACTION</b>${x.recommended_action}</div></div><div class="rec-meta"><strong>${money.format(x.estimated_monthly_savings)}<small>EST. MONTHLY SAVINGS</small></strong><dl><div><dt>Confidence</dt><dd>${x.confidence}</dd></div><div><dt>Risk</dt><dd>${x.risk}</dd></div><div><dt>Complexity</dt><dd>${x.implementation_complexity}</dd></div><div><dt>Application</dt><dd>${x.affected_application}</dd></div><div><dt>Model</dt><dd>${x.affected_model}</dd></div></dl></div></article>`).join('')||'<article class="panel forecast-empty"><h2>No thresholds were exceeded.</h2><p>TokenScope found no material deterministic optimization opportunities in this period.</p></article>'}</section>`) }
function anomaliesPage(d){return shell(`${header('Anomalies','Unusual telemetry patterns compared with trailing local baselines.')}<div class="notice">Method: ${d.method}. Severity reflects evidence magnitude, not business impact.</div><section class="metrics four">${metric('TOTAL FINDINGS',d.anomalies.length,'Detected')}${metric('CRITICAL',d.counts.CRITICAL,'Severity')}${metric('HIGH',d.counts.HIGH,'Severity')}${metric('MEDIUM',d.counts.MEDIUM,'Severity')}</section><article class="panel anomaly-panel"><div class="panel-head"><div><p class="eyebrow">RECENT ANOMALIES</p><h2>Evidence-ranked activity</h2></div><span class="tag">OBSERVED</span></div><div class="anomaly-list">${d.anomalies.map(x=>`<div class="anomaly"><span class="severity ${x.severity.toLowerCase()}">${x.severity}</span><div><strong>${x.entity}</strong><p>${x.explanation}</p><small>${x.evidence}</small></div><div class="anomaly-stats"><b>${x.ratio}x</b><small>BASELINE RATIO</small><em>${x.timestamp}</em></div></div>`).join('')||'<div class="empty-inline">No statistically unusual activity was found in this period.</div>'}</div></article>`) }
function budgetsPage(d){return shell(`${header('Budgets','Track local AI spend against scoped financial limits and projected burn.')}<section class="budget-layout"><div class="budget-list">${d.budgets.map(b=>`<article class="panel budget-card"><div class="panel-head"><div><p class="eyebrow">${b.scope_type.toUpperCase()} ${b.scope_value?'· '+b.scope_value:''}</p><h2>${b.name}</h2></div><span class="severity ${b.risk.toLowerCase()}">${b.risk} RISK</span></div><div class="budget-progress"><i style="width:${Math.min(100,b.used_percent)}%"></i></div><div class="budget-numbers"><span><small>SPENT</small><strong>${money.format(b.spent)}</strong></span><span><small>BUDGET</small><strong>${money.format(b.amount)}</strong></span><span><small>PROJECTED</small><strong>${money.format(b.projected_end_of_period)}</strong></span><span><small>EXHAUSTION</small><strong>${b.estimated_exhaustion_date||'Not projected'}</strong></span></div><button data-delete-budget="${b.budget_id}">Delete</button></article>`).join('')||'<article class="panel forecast-empty"><h2>No budgets configured.</h2><p>Create a local budget to track spend and projected exhaustion.</p></article>'}</div><article class="panel budget-form"><p class="eyebrow">NEW BUDGET</p><h2>Create a spending limit</h2><label>Name<input id="budget-name" placeholder="Monthly AI operations"></label><label>Scope<select id="budget-scope"><option value="organization">Organization</option><option value="department">Department</option><option value="team">Team</option><option value="application">Application</option><option value="provider">Provider</option><option value="model">Model</option></select></label><label>Scope value<input id="budget-value" placeholder="Required outside organization"></label><label>Period<select id="budget-period"><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option><option value="annual">Annual</option></select></label><label>Amount (USD)<input id="budget-amount" type="number" min="0.01" step=".01"></label><button class="primary" id="create-budget">Create budget</button></article></section>`) }
function input(id,label,value,min=0,step=1){return `<label>${label}<input id="${id}" type="number" value="${value}" min="${min}" step="${step}"></label>`}
function textInput(id,label,placeholder=''){return `<label>${label}<input id="${id}" type="text" placeholder="${placeholder}"></label>`}
function scenarioPage(){return shell(`${header('Scenario Lab','Model organizational growth, model migration, and local inference economics.')}<div class="notice">All outputs are calculated from user-supplied assumptions. Output quality is not evaluated.</div><section class="lab-grid"><article class="panel lab-form"><p class="eyebrow">ORGANIZATION CAPACITY</p><h2>Expected adoption scenario</h2><div class="form-grid">${input('sc-employees','Employees',1200,1)}${input('sc-adoption','AI adoption %',42,0,.1)}${input('sc-requests','Requests / user / day',18,0,.1)}${input('sc-input','Average input tokens',8000,0)}${input('sc-output','Average output tokens',900,0)}${input('sc-days','Working days / month',22,1)}${input('sc-growth','Monthly growth %',8,-100,.1)}${input('sc-cache','Cache hit %',12,0,.1)}${input('sc-retry','Retry rate %',4,0,.1)}${input('sc-app-growth','Application growth %',5,-100,.1)}</div><h3>MODEL MIX</h3><div class="mix-grid"><span>Economy share<input id="sc-econ-share" type="number" value="60"></span><span>Input $/1M<input id="sc-econ-in" type="number" value="0.5" step=".01"></span><span>Output $/1M<input id="sc-econ-out" type="number" value="1.5" step=".01"></span><span>Premium share<input id="sc-prem-share" type="number" value="40"></span><span>Input $/1M<input id="sc-prem-in" type="number" value="3" step=".01"></span><span>Output $/1M<input id="sc-prem-out" type="number" value="12" step=".01"></span></div><button class="primary" id="run-scenario">Calculate scenario</button></article><article class="panel lab-results" id="scenario-results"><div class="empty-inline">Adjust assumptions and calculate the expected capacity scenario.</div></article></section><section class="lower-grid lab-secondary"><article class="panel"><p class="eyebrow">MODEL MIGRATION</p><h2>Compare at observed traffic volume</h2><p class="help">Requires existing demo, imported, or live telemetry.</p><label>Application<select id="mig-app">${(state.options.application||[]).map(x=>`<option>${x}</option>`).join('')}</select></label>${textInput('mig-model','Alternative model ID','llama-3.1-8b')}${input('mig-input','Alternative input $/1M',.1,0,.01)}${input('mig-output','Alternative output $/1M',.1,0,.01)}<button id="run-migration">Compare model cost</button><div id="migration-results"></div></article><article class="panel"><p class="eyebrow">LOCAL VS CLOUD</p><h2>Infrastructure break-even</h2><div class="form-grid compact">${input('lc-input','Monthly input tokens',1000000000,0)}${input('lc-output','Monthly output tokens',200000000,0)}${input('lc-cloud-in','Cloud input $/1M',3,0,.01)}${input('lc-cloud-out','Cloud output $/1M',12,0,.01)}${input('lc-gpus','GPU quantity',2,1)}${input('lc-price','Purchase price / GPU',18000,0)}${input('lc-watts','Power draw watts',700,0)}${input('lc-electricity','Electricity $/kWh',.15,0,.01)}${input('lc-util','Utilization %',55,1,.1)}${input('lc-tps','Estimated tokens/sec',120,1,.1)}${input('lc-life','Hardware life months',36,1)}${input('lc-maint','Monthly maintenance',400,0)}</div><button id="run-local-cloud">Calculate break-even</button><div id="local-cloud-results"></div></article></section>`) }
function integrationsPage(d){const cards=d.catalog.map(x=>`<article class="panel integration-card"><div class="integration-icon">${x.kind==='opentelemetry'?'OT':x.name.slice(0,2).toUpperCase()}</div><div><span>${x.optional?'OPTIONAL — NOT REQUIRED':'PRIMARY INGESTION'}</span><h2>${x.name}</h2><p>${x.description}</p></div>${x.kind==='opentelemetry'?'<button data-copy-otel>View setup</button>':`<button data-configure="${x.kind}" data-name="${x.name}" data-url="${x.default_url}">Configure</button>`}</article>`).join('');return shell(`${header('Integrations','Connect local AI and existing observability without replacing instrumentation.')}<div class="privacy-banner"><strong>METADATA-ONLY DEFAULT</strong><span>Tokens, models, latency, applications, and errors are enabled. User identifiers and content are disabled.</span></div><section class="integration-grid">${cards}</section><section class="integration-bottom"><article class="panel"><div class="panel-head"><div><p class="eyebrow">CONFIGURED CONNECTIONS</p><h2>${d.configured.length} local integrations</h2></div></div>${d.configured.map(x=>`<div class="configured"><span class="pulse"></span><div><strong>${x.name}</strong><small>${x.kind} · ${x.base_url}</small></div><em>${x.status}</em><button data-remove-integration="${x.integration_id}">Remove</button></div>`).join('')||'<div class="empty-inline">No local endpoints configured yet. OTLP and callback ingestion are already available.</div>'}</article><article class="panel optional-cloud"><p class="eyebrow">CLOUD PROVIDERS</p><h2>Commercial integrations</h2><p>OpenAI, Anthropic, Gemini, Azure OpenAI, and Bedrock remain disabled.</p><span>${d.commercial_providers}</span><button disabled>COMING IN MILESTONE 7</button></article></section><div class="modal-backdrop hidden" id="integration-modal"><section class="panel integration-modal"><button class="modal-close" id="close-integration">×</button><p class="eyebrow" id="int-eyebrow">CONNECT LOCAL ENDPOINT</p><h2 id="int-title">Configure</h2><input type="hidden" id="int-kind"><label>Name<input id="int-name"></label><label>Base URL<input id="int-url"></label><label class="check"><input type="checkbox" id="int-identity"> Collect user identifiers <b>OFF BY DEFAULT</b></label><div id="int-result" class="help">Connection tests only contact the configured private endpoint.</div><div class="modal-actions"><button id="test-integration">Test connection</button><button class="primary" id="save-integration">Save configuration</button></div></section></div><div class="modal-backdrop hidden" id="otel-modal"><section class="panel integration-modal"><button class="modal-close" id="close-otel">×</button><p class="eyebrow">OPENTELEMETRY / OTLP HTTP JSON</p><h2>Send GenAI spans to TokenScope</h2><p class="help">Keep existing instrumentation and configure this local trace destination:</p><code>POST http://127.0.0.1:8000/api/v1/otlp/v1/traces</code><p class="help">Recognized attributes include gen_ai.request.model, gen_ai.response.model, gen_ai.provider.name, gen_ai.usage.input_tokens, and gen_ai.usage.output_tokens.</p></section></div>`) }
function settingsPage(d){const privacyFields=['collect_token_counts','collect_latency','collect_model','collect_provider','collect_application','collect_workload','collect_department','collect_team','collect_user_identity','collect_prompt','collect_response'];return shell(`${header('Settings & security','Optional providers, privacy, retention, exports, and deployment hardening.')}<section class="security-strip">${Object.entries(d.security).filter(([,v])=>typeof v!=='object').slice(0,5).map(([k,v])=>`<span><small>${k.replaceAll('_',' ')}</small><strong>${String(v)}</strong></span>`).join('')}</section><div class="warning-note">${d.security.warning}</div><section class="settings-grid"><article class="panel cloud-settings"><p class="eyebrow">OPTIONAL CLOUD PROVIDERS</p><h2>User-supplied credential references</h2><p class="help">${d.cloud.secrets_policy}</p>${d.cloud.catalog.map(x=>`<div class="cloud-row"><div><strong>${x.name}</strong><small>${x.notice}</small></div><label>Environment variable<input data-cloud-env="${x.provider}" value="${x.configuration?.credential_env_var||x.default_env_var}"></label><label class="toggle"><input type="checkbox" data-cloud-enabled="${x.provider}" ${x.configuration?.enabled?'checked':''}> Enabled</label><span class="credential ${x.configuration?.credential_available?'ready':'missing'}">${x.configuration?.credential_available?'CREDENTIAL AVAILABLE':'NOT PRESENT'}</span><button data-save-cloud="${x.provider}">Save</button></div>`).join('')}</article><article class="panel governance"><p class="eyebrow">DATA RETENTION</p><h2>Explicit deletion policy</h2><label>Retention window<select id="retention-days"><option value="">Unlimited</option>${[30,90,180,365].map(x=>`<option value="${x}" ${d.retention.days===x?'selected':''}>${x} days</option>`).join('')}</select></label><p class="help">${d.retention.notice}</p><button id="save-retention">Save policy</button><button class="danger-button" id="apply-retention">Apply deletion now</button><p class="eyebrow export-title">APPEARANCE</p><div class="theme-buttons"><button data-theme="dark">Dark</button><button data-theme="light">Light</button><button data-theme="system">System</button></div><p class="eyebrow export-title">SAFE EXPORTS</p><a class="button-link" href="${API}/export/configuration" target="_blank">Export configuration (no secrets)</a><a class="button-link" href="${API}/export/events.csv" target="_blank">Export telemetry CSV</a></article></section><section class="panel privacy-settings"><p class="eyebrow">TELEMETRY PRIVACY</p><h2>Data minimization controls</h2><p class="help">${d.privacy.notice}</p><div>${privacyFields.map(key=>`<label class="toggle"><input type="checkbox" data-privacy="${key}" ${d.privacy[key]?'checked':''}> ${key.replace('collect_','').replaceAll('_',' ')}</label>`).join('')}</div><button id="save-privacy">Save privacy controls</button>${d.privacy.content_warning?'<div class="warning-note">CONTENT COLLECTION ENABLED — prompts or responses may contain sensitive data.</div>':''}</section><article class="panel audit-panel"><div class="panel-head"><div><p class="eyebrow">AUDIT LOG</p><h2>Recent configuration actions</h2></div><span class="tag">LOCAL</span></div><div class="audit-list">${d.audit.map(x=>`<div><span>${new Date(x.timestamp).toLocaleString()}</span><strong>${x.action}</strong><em>${x.target_type} · ${x.target_id||'—'}</em><b>${x.outcome}</b></div>`).join('')||'<div class="empty-inline">No configuration changes have been recorded.</div>'}</div></article>`) }
function reportsPage(d){const r=d.report,e=d.efficiency;return shell(`${header('Executive reports','A progressively disclosed summary of observed usage, estimates, risks, and opportunities.')}<div class="report-actions"><span>${new Date(r.generated_at).toLocaleString()} · ${r.period_days} days</span><a class="button-link" href="${API}/reports/executive.csv?days=${r.period_days}">Download CSV</a></div><section class="metrics four">${metric('TOTAL TOKENS',num.format(r.usage.tokens),'Observed')}${metric('AI SPEND',money.format(r.usage.spend),'Estimated')}${metric('REQUESTS',num.format(r.usage.requests),'Observed')}${metric('POTENTIAL SAVINGS',money.format(r.optimization.estimated_monthly_savings),'Estimated')}</section><section class="report-grid"><article class="panel efficiency-panel"><p class="eyebrow">AI EFFICIENCY</p><div class="efficiency-score"><strong>${e.score}</strong><span>/ 100<small>Operational efficiency</small></span></div><p class="help">${e.disclaimer}</p>${Object.entries(e.components).map(([key,value])=>`<div class="component"><span>${key.replaceAll('_',' ')}</span><i><em style="width:${value}%"></em></i><strong>${value}</strong><small>${Math.round(e.weights[key]*100)}% weight</small></div>`).join('')}<details><summary>How is this calculated?</summary><p>${e.formula}. Components normalize cost/request, cached-input reuse, retries, failures, context utilization, and reliability.</p></details></article><article class="panel"><p class="eyebrow">LARGEST APPLICATIONS</p><h2>Observed token consumers</h2>${bars(r.largest_applications,'application','tokens')}</article><article class="panel"><p class="eyebrow">BUDGET & ANOMALY RISK</p><h2>${r.anomalies.count} anomalies</h2>${r.budgets.map(b=>`<div class="report-risk"><span class="severity ${b.risk.toLowerCase()}">${b.risk}</span><strong>${b.name}</strong><em>${money.format(b.projected_end_of_period)} projected</em></div>`).join('')||'<div class="empty-inline">No budgets configured.</div>'}</article><article class="panel"><p class="eyebrow">OPTIMIZATION</p><h2>${r.optimization.count} opportunities</h2>${r.top_opportunities.map(x=>`<div class="report-opportunity"><strong>${x.title}</strong><span>${money.format(x.estimated_monthly_savings)} / month</span><small>${x.labels.evidence} evidence · ${x.labels.savings} savings</small></div>`).join('')||'<div class="empty-inline">No thresholds exceeded.</div>'}</article></section>`) }
function modelsPage(d){return shell(`${header('Model Intelligence','Compare configured prices with observed model performance and user-supplied evaluations.')}<div class="notice">${d.quality_policy} Select 2–5 models for comparison.</div><section class="model-layout"><article class="panel model-inventory"><div class="panel-head"><div><p class="eyebrow">MODEL INVENTORY</p><h2>${d.models.length} observed or configured models</h2></div><button class="primary" id="compare-models">Compare selected</button></div><div class="model-rows">${d.models.map(x=>`<label class="model-row"><input type="checkbox" data-model-select value="${x.model}"><div><strong>${x.model}</strong><small>${x.provider} · ${x.deployment}</small></div><span><small>REQUESTS</small>${num.format(x.requests)}</span><span><small>SUCCESS</small>${x.success_rate===null?'—':x.success_rate+'%'}</span><span><small>LATENCY</small>${x.observed_latency_ms===null?'—':Math.round(x.observed_latency_ms)+' ms'}</span><span><small>HISTORICAL COST</small>${money.format(x.historical_cost)}</span><em>${x.quality_metrics.length?x.quality_metrics.length+' QUALITY METRICS':'NO QUALITY DATA'}</em></label>`).join('')}</div></article><article class="panel evaluation-form"><p class="eyebrow">ADD EVALUATION EVIDENCE</p><h2>User-supplied quality metric</h2><label>Model<select id="eval-model">${d.models.map(x=>`<option>${x.model}</option>`).join('')}</select></label><label>Metric<input id="eval-metric" placeholder="task_accuracy"></label><div>${input('eval-score','Score',90,0,.01)}${input('eval-max','Maximum score',100,.01,.01)}</div>${input('eval-samples','Sample size',100,1)}<label>Source<input id="eval-source" placeholder="Internal benchmark v1"></label><label>Application<input id="eval-app" placeholder="Optional"></label><button class="primary" id="save-evaluation">Save evaluation</button><p class="help">TokenScope stores this as user-supplied evidence and never invents model quality.</p></article></section><section class="panel model-comparison" id="model-comparison"><div class="empty-inline">Select 2–5 models to compare price, observed operations, cost, and supplied evaluations.</div></section>`) }
function onboarding(){return `<main class="onboarding"><div class="welcome-brand"><span class="logo">T</span><strong>TokenScope</strong><small>OPEN AI USAGE INTELLIGENCE</small></div><section class="welcome"><span class="demo-label">LOCAL-FIRST · NO API KEYS REQUIRED</span><h1>Welcome to TokenScope</h1><p>Track, forecast, and optimize AI usage without sending telemetry anywhere.</p><div class="start-grid"><button class="start-card featured" id="demo"><i>↗</i><b>Explore Demo Data</b><span>Generate 30 days of realistic usage locally.</span><em>RECOMMENDED</em></button><button class="start-card" data-go="import"><i>↓</i><b>Import Usage Data</b><span>Preview and validate CSV or JSON.</span><em>AVAILABLE</em></button><button class="start-card"><i>⌁</i><b>Connect Local AI</b><span>Ollama and vLLM adapters arrive in Milestone 6.</span><em>COMING SOON</em></button><button class="start-card"><i>⚙</i><b>Configure Telemetry</b><span>REST ingestion is ready at port 8000.</span><em>API READY</em></button></div></section></main>`}
function wizard(){const choices=[['demo','Explore Demo Data','Recommended'],['local','Connect Local AI','Detect localhost services'],['telemetry','Connect Existing Telemetry','Use OTLP or compatible APIs'],['import','Import Existing Data','CSV or JSON'],['advanced','Advanced Setup','Configure manually']];if(state.wizardStep===1)return `<main class="setup-wizard"><section><span class="logo">AI</span><p class="eyebrow">AI OPTIMIZATION TOOL</p><h1>Understand, forecast, and optimize AI usage.</h1><p>No paid AI API keys are required.</p><button class="primary" id="wizard-start">Get Started</button></section></main>`;if(state.wizardStep===2)return `<main class="setup-wizard"><section><p class="eyebrow">HOW WOULD YOU LIKE TO BEGIN?</p><h1>Choose a local-first starting point.</h1><div class="wizard-choices">${choices.map(([id,title,note])=>`<button data-wizard-choice="${id}" class="${state.wizardChoice===id?'selected':''}"><strong>${title}</strong><span>${note}</span></button>`).join('')}</div><button class="primary" id="wizard-next">Continue</button></section></main>`;return `<main class="setup-wizard"><section><p class="eyebrow">PRIVACY DEFAULTS</p><h1>Your metadata stays local.</h1><p>AI Optimization Tool does not require prompt or response content for core usage, cost, forecasting, or optimization analytics.</p><div class="privacy-summary"><div><strong>ON</strong><span>Token counts, model, provider, latency, application/workload, cost metadata</span></div><div><strong>OFF</strong><span>Prompt content, response content, direct user identity</span></div></div><label class="toggle"><input id="wizard-content" type="checkbox"> Enable prompt and response content collection (optional)</label><div class="wizard-actions"><button id="wizard-back">Back</button><button class="primary" id="wizard-finish">Finish Setup</button></div></section></main>`}
function render(){const root=document.querySelector('#app');if(state.loading){root.innerHTML='<div class="center-state startup-state"><p class="eyebrow">AI OPTIMIZATION TOOL</p><h2>Starting local services…</h2><dl><div><dt>Database</dt><dd>Checking</dd></div><div><dt>Analytics</dt><dd>Starting</dd></div><div><dt>Telemetry</dt><dd>Starting</dd></div><div><dt>Dashboard</dt><dd>Waiting</dd></div></dl><span class="loader"></span></div>';return}if(state.error){if(state.page==='forecasts'){root.innerHTML=forecastEmpty(state.error);bind();return}root.innerHTML=`<div class="center-state error-state"><span>!</span><h1>Backend unavailable</h1><p>TokenScope could not connect to the local telemetry service.</p><small>Your telemetry data has not been deleted.</small><details><summary>View Diagnostics</summary><code>${escapeHtml(state.error)}</code></details><button id="retry">Retry Connection</button></div>`;root.querySelector('#retry').onclick=load;return}if(!state.application?.first_run_complete){root.innerHTML=wizard();bindWizard();return}const pages={overview:()=>overview(state.data),usage:()=>analyticsPage(state.data),costs:()=>analyticsPage(state.data,true),models:()=>modelsPage(state.data),forecasts:()=>forecastPage(state.data),optimization:()=>optimizationPage(state.data),anomalies:()=>anomaliesPage(state.data),budgets:()=>budgetsPage(state.data),scenario:scenarioPage,reports:()=>reportsPage(state.data),integrations:()=>integrationsPage(state.data),settings:()=>settingsPage(state.data),import:importPage,pricing:()=>pricingPage(state.data)};root.innerHTML=(pages[state.page]||pages.overview)();bind()}
function bindWizard(){document.querySelector('#wizard-start')?.addEventListener('click',()=>{state.wizardStep=2;render()});document.querySelectorAll('[data-wizard-choice]').forEach(b=>b.onclick=()=>{state.wizardChoice=b.dataset.wizardChoice;render()});document.querySelector('#wizard-next')?.addEventListener('click',()=>{state.wizardStep=3;render()});document.querySelector('#wizard-back')?.addEventListener('click',()=>{state.wizardStep=2;render()});document.querySelector('#wizard-finish')?.addEventListener('click',async()=>{const content=document.querySelector('#wizard-content')?.checked||false;await api('/application/setup',{method:'PUT',body:JSON.stringify({choice:state.wizardChoice,privacy:{collect_prompt:content,collect_response:content}})});state.application=null;state.page=state.wizardChoice==='import'?'import':'overview';location.hash=state.page;load()})}
function persist(){localStorage.setItem('ts-days',state.days);localStorage.setItem('ts-filters',JSON.stringify(state.filters))}
function bind(){document.querySelectorAll('[data-page]').forEach(a=>a.onclick=e=>{e.preventDefault();state.page=a.dataset.page;location.hash=state.page;load()});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.page=b.dataset.go;location.hash=state.page;load()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{await api('/application/mode',{method:'PUT',body:JSON.stringify({mode:b.dataset.mode})});state.application.mode=b.dataset.mode;state.page='overview';location.hash='overview';load()});document.querySelector('#remove-demo')?.addEventListener('click',async()=>{if(confirm('Remove all demo telemetry? Your imported and live telemetry will remain.')){await api('/demo',{method:'DELETE'});load()}});document.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{state.days=+b.dataset.days;persist();load()});document.querySelectorAll('[data-filter]').forEach(s=>s.onchange=()=>{state.filters[s.dataset.filter]=s.value;persist();load()});document.querySelector('#clear-filters')?.addEventListener('click',()=>{state.filters={};persist();load()});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{state.group=b.dataset.group;load()});document.querySelectorAll('[data-horizon]').forEach(b=>b.onclick=()=>{state.forecastHorizon=+b.dataset.horizon;load()});document.querySelector('#forecast-metric')?.addEventListener('change',e=>{state.forecastMetric=e.target.value;load()});document.querySelector('#refresh')?.addEventListener('click',load);document.querySelector('#demo')?.addEventListener('click',async()=>{await api('/demo?days=30',{method:'POST'});load()});bindImport();bindPricing();bindBudgets();bindScenario();bindIntegrations();bindSettings();bindModels();bindCommand();bindLive()}
function bindImport(){if(!importWorkflow){importWorkflow=new ImportWorkflow(api,money,num)}importWorkflow.bind();loadImportHistory()}
async function loadImportHistory(){const list=document.querySelector('#history-list');if(!list)return;try{const history=await api('/import/history');list.innerHTML=history.imports?.length?history.imports.map(imp=>`<div class="history-item"><div class="history-info"><strong title="${escapeHtml(imp.filename)}">${escapeHtml(imp.filename)}</strong><time>${new Date(imp.created_at).toLocaleString()}</time></div><div class="history-stats"><span><strong>${num.format(imp.inserted_rows)}</strong> / ${num.format(imp.total_rows)} rows</span><span class="status ${imp.status.toLowerCase()}">${imp.status}</span></div></div>`).join(''):'<div class="empty-inline">No imports yet.</div>'}catch(error){list.innerHTML='<div class="empty-inline">Import history is temporarily unavailable.</div>'}}
function applyTheme(theme){localStorage.setItem('ts-theme',theme);const resolved=theme==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):theme;document.body.classList.toggle('light-theme',resolved==='light')}
function bindSettings(){document.querySelectorAll('[data-save-cloud]').forEach(b=>b.onclick=async()=>{const provider=b.dataset.saveCloud,payload={provider,enabled:document.querySelector(`[data-cloud-enabled="${provider}"]`).checked,credential_env_var:document.querySelector(`[data-cloud-env="${provider}"]`).value,endpoint:null};try{await api('/cloud-providers/'+provider,{method:'PUT',body:JSON.stringify(payload)});load()}catch(e){alert(e.message)}});document.querySelector('#save-retention')?.addEventListener('click',async()=>{const raw=document.querySelector('#retention-days').value;await api('/settings/retention',{method:'PUT',body:JSON.stringify({days:raw?+raw:null})});load()});document.querySelector('#apply-retention')?.addEventListener('click',async()=>{if(confirm('Permanently delete telemetry outside the configured retention window?')){const r=await api('/settings/retention/apply',{method:'POST'});alert(`Deleted ${r.deleted} records.`);load()}});document.querySelector('#clear-telemetry-data')?.addEventListener('click',()=>{state.telemetryReset={open:true,running:false,message:''};render()});document.querySelector('#cancel-telemetry-clear')?.addEventListener('click',()=>{if(state.telemetryReset.running)return;state.telemetryReset={open:false,running:false,message:state.telemetryReset.message};render()});document.querySelector('#confirm-telemetry-clear')?.addEventListener('click',clearTelemetryData);document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>applyTheme(b.dataset.theme));document.querySelector('#save-privacy')?.addEventListener('click',async()=>{const payload={};document.querySelectorAll('[data-privacy]').forEach(x=>payload[x.dataset.privacy]=x.checked);if((payload.collect_prompt||payload.collect_response)&&!confirm('Content may contain sensitive data. Enable content collection settings anyway?'))return;await api('/settings/privacy',{method:'PUT',body:JSON.stringify(payload)});load()})}
async function refreshTelemetryBaseline(){state.options=await api('/filters');const requests=[api('/overview?'+query()),api('/analytics?'+query({group_by:state.group})),api('/forecasts?'+query({metric:state.forecastMetric,horizon:state.forecastHorizon,training_days:180})).catch(error=>({error:error.message})),api('/optimization?days='+state.days),api('/anomalies?days=90'),api('/reports/executive?days='+state.days).catch(error=>({error:error.message})),api('/efficiency?days='+state.days),api('/import/history')];await Promise.all(requests);await load()}
async function clearTelemetryData(){if(state.telemetryReset.running)return;state.telemetryReset.running=true;render();try{await api('/telemetry',{method:'DELETE'});state.telemetryReset={open:false,running:false,message:'Telemetry cleared. Baseline restored.'};await refreshTelemetryBaseline()}catch(e){state.telemetryReset={open:true,running:false,message:e.message};render()}}
function telemetryResetModal(){const reset=state.telemetryReset;return `<div class="modal-backdrop ${reset.open?'':'hidden'}" id="telemetry-reset-modal"><section class="panel integration-modal" role="dialog" aria-modal="true" aria-labelledby="telemetry-reset-title"><p class="eyebrow">DATA MANAGEMENT</p><h2 id="telemetry-reset-title">Clear Telemetry Data</h2><p class="help">This permanently removes imported telemetry and telemetry-derived analysis from this device. Application settings and configuration will be preserved.</p>${reset.open&&reset.message?`<div class="warning-note" id="telemetry-reset-message">${escapeHtml(reset.message)}</div>`:''}<div class="modal-actions"><button id="cancel-telemetry-clear" ${reset.running?'disabled':''}>Cancel</button><button class="danger-button" id="confirm-telemetry-clear" ${reset.running?'disabled':''}>${reset.running?'Clearing...':'Clear Telemetry'}</button></div></section></div>`}
function comparisonTable(d){const metrics=[['Provider','provider',x=>x],['Deployment','deployment',x=>x],['Input price / 1M','input_price_per_million',money.format],['Output price / 1M','output_price_per_million',money.format],['Observed requests','requests',num.format],['Success rate','success_rate',x=>x===null?'—':x+'%'],['Average latency','observed_latency_ms',x=>x===null?'—':Math.round(x)+' ms'],['Tokens / second','observed_tokens_per_second',x=>x===null?'—':x],['Historical cost','historical_cost',money.format],['Est. monthly cost','estimated_monthly_cost_at_observed_rate',money.format],['Average context','average_context_tokens',x=>x===null?'—':num.format(x)]];return `<div class="compare-disclaimer">${d.disclaimer}</div><div class="compare-table" style="--models:${d.models.length}"><div class="compare-row compare-head"><strong>METRIC</strong>${d.models.map(x=>`<strong>${x.model}</strong>`).join('')}</div>${metrics.map(([label,key,format])=>`<div class="compare-row"><span>${label}</span>${d.models.map(x=>`<b>${format(x[key])}</b>`).join('')}</div>`).join('')}<div class="quality-section"><h3>USER-SUPPLIED QUALITY EVIDENCE</h3>${d.models.map(x=>`<article><strong>${x.model}</strong>${x.quality_metrics.map(q=>`<span>${q.metric}<b>${q.normalized_score_percent}%</b><small>${q.total_samples} samples · ${q.source}</small></span>`).join('')||'<em>No quality evaluation supplied.</em>'}</article>`).join('')}</div></div>`}
function bindModels(){document.querySelector('#compare-models')?.addEventListener('click',async()=>{const selected=[...document.querySelectorAll('[data-model-select]:checked')].map(x=>x.value);if(selected.length<2||selected.length>5)return alert('Select between 2 and 5 models.');try{const d=await api('/models/compare?days='+state.days+'&models='+encodeURIComponent(selected.join(',')));document.querySelector('#model-comparison').innerHTML=comparisonTable(d);document.querySelector('#model-comparison').scrollIntoView({behavior:'smooth'})}catch(e){alert(e.message)}});document.querySelector('#save-evaluation')?.addEventListener('click',async()=>{const payload={model:document.querySelector('#eval-model').value,metric:document.querySelector('#eval-metric').value,score:value('eval-score'),maximum_score:value('eval-max'),sample_size:value('eval-samples'),source:document.querySelector('#eval-source').value,application:document.querySelector('#eval-app').value||null,workload:null,notes:null};try{await api('/evaluations',{method:'POST',body:JSON.stringify(payload)});load()}catch(e){alert(e.message)}})}
function bindCommand(){const modal=document.querySelector('#command-modal'),input=document.querySelector('#command-search'),results=document.querySelector('#command-results');const open=()=>{modal?.classList.remove('hidden');input?.focus()},close=()=>modal?.classList.add('hidden');document.querySelector('#global-search')?.addEventListener('click',open);document.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();open()}if(e.key==='Escape')close()};document.querySelectorAll('[data-command-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.commandPage;location.hash=state.page;load()});let timer;input?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(input.value.length<2)return;const data=await api('/search?q='+encodeURIComponent(input.value));results.innerHTML=data.results.map(x=>`<button data-search-result="${x.type}" data-label="${x.label}"><span>${x.type.toUpperCase()}</span>${x.label}</button>`).join('')||'<div class="empty-inline">No matching telemetry entities.</div>';document.querySelectorAll('[data-search-result]').forEach(b=>b.onclick=()=>{const type=b.dataset.searchResult;if(type!=='budget')state.filters[type]=b.dataset.label;state.page=type==='budget'?'budgets':'usage';persist();location.hash=state.page;load()})},200)})}
function bindLive(){liveSource?.close();if(!document.querySelector('#live-rpm'))return;liveSource=new EventSource(API+'/live/stream');liveSource.addEventListener('metrics',event=>{const x=JSON.parse(event.data),rpm=document.querySelector('#live-rpm'),tpm=document.querySelector('#live-tpm');if(rpm)rpm.textContent=`${x.requests_per_minute} requests/min`;if(tpm)tpm.textContent=`${num.format(x.tokens_per_minute)} tokens/min · ${x.recent_errors} errors`})}
function bindPricing(){document.querySelector('#save-price')?.addEventListener('click',async()=>{const model=document.querySelector('#price-model').value.trim();if(!model)return alert('Model ID is required.');const today=new Date().toISOString().slice(0,10),payload={model_id:model,provider:document.querySelector('#price-provider').value||'custom',input_price_per_million:+document.querySelector('#price-input').value,output_price_per_million:+document.querySelector('#price-output').value,cached_input_price_per_million:+document.querySelector('#price-cached').value,currency:'USD',effective_date:today,last_verified:today,source:'User override'};try{await api('/pricing/'+encodeURIComponent(model),{method:'PUT',body:JSON.stringify(payload)});load()}catch(e){alert(e.message)}})}
function bindIntegrations(){const modal=document.querySelector('#integration-modal'),otel=document.querySelector('#otel-modal');document.querySelectorAll('[data-configure]').forEach(b=>b.onclick=()=>{modal.classList.remove('hidden');document.querySelector('#int-kind').value=b.dataset.configure;document.querySelector('#int-name').value=b.dataset.name;document.querySelector('#int-url').value=b.dataset.url;document.querySelector('#int-title').textContent='Connect '+b.dataset.name});document.querySelector('#close-integration')?.addEventListener('click',()=>modal.classList.add('hidden'));document.querySelector('[data-copy-otel]')?.addEventListener('click',()=>otel.classList.remove('hidden'));document.querySelector('#close-otel')?.addEventListener('click',()=>otel.classList.add('hidden'));const payload=()=>({kind:document.querySelector('#int-kind').value,name:document.querySelector('#int-name').value,base_url:document.querySelector('#int-url').value,collect_user_identifiers:document.querySelector('#int-identity').checked});document.querySelector('#test-integration')?.addEventListener('click',async()=>{const box=document.querySelector('#int-result');box.textContent='Testing private endpoint…';try{const r=await api('/integrations/test',{method:'POST',body:JSON.stringify(payload())});box.innerHTML=r.reachable?`<b class="good">CONNECTED</b> · ${r.models.length} models discovered`:`<b class="bad">UNREACHABLE</b> · ${r.error}`}catch(e){box.innerHTML=`<b class="bad">BLOCKED</b> · ${e.message}`}});document.querySelector('#save-integration')?.addEventListener('click',async()=>{try{await api('/integrations',{method:'POST',body:JSON.stringify(payload())});modal.classList.add('hidden');load()}catch(e){alert(e.message)}});document.querySelectorAll('[data-remove-integration]').forEach(b=>b.onclick=async()=>{if(confirm('Remove this integration configuration?')){await api('/integrations/'+b.dataset.removeIntegration,{method:'DELETE'});load()}})}
function bindBudgets(){document.querySelector('#create-budget')?.addEventListener('click',async()=>{const payload={name:document.querySelector('#budget-name').value,scope_type:document.querySelector('#budget-scope').value,scope_value:document.querySelector('#budget-value').value||null,period:document.querySelector('#budget-period').value,amount:+document.querySelector('#budget-amount').value,currency:'USD',active:true};try{await api('/budgets',{method:'POST',body:JSON.stringify(payload)});load()}catch(e){alert(e.message)}});document.querySelectorAll('[data-delete-budget]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this budget?')){await api('/budgets/'+b.dataset.deleteBudget,{method:'DELETE'});load()}})}
function value(id){return +document.querySelector('#'+id).value}
function resultCards(items){return `<div class="result-cards">${items.map(([label,value])=>`<span><small>${label}</small><strong>${value}</strong></span>`).join('')}</div>`}
function bindScenario(){document.querySelector('#run-scenario')?.addEventListener('click',async()=>{const payload={name:'Expected',employees:value('sc-employees'),adoption_percent:value('sc-adoption'),requests_per_user_day:value('sc-requests'),average_input_tokens:value('sc-input'),average_output_tokens:value('sc-output'),working_days_month:value('sc-days'),monthly_growth_percent:value('sc-growth'),cache_hit_percent:value('sc-cache'),retry_percent:value('sc-retry'),application_growth_percent:value('sc-app-growth'),model_mix:[{model:'Economy mix',share_percent:value('sc-econ-share'),input_price_per_million:value('sc-econ-in'),output_price_per_million:value('sc-econ-out')},{model:'Premium mix',share_percent:value('sc-prem-share'),input_price_per_million:value('sc-prem-in'),output_price_per_million:value('sc-prem-out')}]};try{const r=await api('/simulator/scenario',{method:'POST',body:JSON.stringify(payload)});document.querySelector('#scenario-results').innerHTML=`<p class="eyebrow">CALCULATED CAPACITY</p><h2>${r.scenario} scenario</h2>${resultCards([['Active AI users',num.format(r.active_ai_users)],['Monthly requests',num.format(r.monthly_requests)],['Monthly tokens',num.format(r.monthly_total_tokens)],['Monthly spend',money.format(r.monthly_spend)],['Annual spend',money.format(r.annual_spend)],['Next month',money.format(r.next_month_spend)],['Cache savings',money.format(r.cache_savings)],['Retry overhead',num.format(r.retry_overhead_requests)]])}<div class="assumption">CALCULATED · QUALITY NOT EVALUATED</div>`}catch(e){alert(e.message)}});document.querySelector('#run-migration')?.addEventListener('click',async()=>{const payload={application:document.querySelector('#mig-app').value,alternative_model:document.querySelector('#mig-model').value,alternative_input_price_per_million:value('mig-input'),alternative_output_price_per_million:value('mig-output'),days:30};try{const r=await api('/simulator/model-migration',{method:'POST',body:JSON.stringify(payload)});document.querySelector('#migration-results').innerHTML=`${resultCards([['Observed model',r.observed.model],['Observed cost',money.format(r.observed.cost)],['Alternative cost',money.format(r.alternative.estimated_cost)],['Estimated savings',money.format(r.estimated_savings)],['Annualized savings',money.format(r.estimated_annual_savings)]])}<div class="warning-note">${r.disclaimer}</div>`}catch(e){alert(e.message)}});document.querySelector('#run-local-cloud')?.addEventListener('click',async()=>{const payload={monthly_input_tokens:value('lc-input'),monthly_output_tokens:value('lc-output'),cloud_input_price_per_million:value('lc-cloud-in'),cloud_output_price_per_million:value('lc-cloud-out'),gpu_name:'Local GPU',gpu_quantity:value('lc-gpus'),gpu_purchase_price:value('lc-price'),power_draw_watts:value('lc-watts'),electricity_rate_kwh:value('lc-electricity'),utilization_percent:value('lc-util'),estimated_tokens_second:value('lc-tps'),hardware_life_months:value('lc-life'),monthly_maintenance_cost:value('lc-maint'),monthly_hosting_cost:0};try{const r=await api('/simulator/local-vs-cloud',{method:'POST',body:JSON.stringify(payload)});document.querySelector('#local-cloud-results').innerHTML=`${resultCards([['Cloud / month',money.format(r.cloud_monthly_cost)],['Local / month',money.format(r.local_monthly_cost)],['Monthly difference',money.format(r.monthly_difference)],['Break-even tokens',num.format(r.break_even_monthly_tokens)],['Capacity tokens',num.format(r.estimated_monthly_capacity_tokens)],['Required capacity',r.capacity_utilization_required_percent.toFixed(2)+'%']])}<div class="warning-note">${r.disclaimer}</div>`}catch(e){alert(e.message)}})}
const normalRender=render;
function recoveryMarkup(f){const when=f.timestamp_unix?new Date(f.timestamp_unix*1000).toISOString():'Unavailable';return `<div class="center-state recovery-state"><p class="eyebrow">AI OPTIMIZATION TOOL</p><span class="recovery-icon">!</span><h1>Unable to start local services.</h1><p>Your telemetry data has not been deleted.</p><div class="recovery-summary">${escapeHtml(f.summary||'An unexpected local startup failure occurred.')}</div><div class="recovery-actions"><button class="primary" id="startup-retry">Retry</button><button id="startup-details">View Details</button><button id="startup-logs">Open Logs</button><button id="startup-exit">Exit</button></div><section class="recovery-details hidden" id="startup-detail-panel"><dl><div><dt>Failure category</dt><dd>${escapeHtml(f.category)}</dd></div><div><dt>Timestamp</dt><dd>${escapeHtml(when)}</dd></div><div><dt>Backend executable</dt><dd>${escapeHtml(f.backend_executable)}</dd></div><div><dt>Bind address</dt><dd>${escapeHtml(f.bind_address)}</dd></div><div><dt>Health check</dt><dd>${escapeHtml(f.health_check)}</dd></div><div><dt>Child exit code</dt><dd>${escapeHtml(f.child_exit_code??'Not available')}</dd></div><div><dt>Application version</dt><dd>${escapeHtml(f.application_version)}</dd></div></dl></section><p class="recovery-feedback" id="startup-feedback" role="status"></p></div>`}
function bindRecovery(root,f){root.querySelector('#startup-retry').onclick=async()=>{state.startup={status:'STARTING'};state.loading=true;render();try{await desktopInvoke('retry_backend');setTimeout(checkDesktopStartup,250)}catch(error){state.loading=false;state.startup={status:'FAILED',failure:{...f,summary:String(error)}};render()}};root.querySelector('#startup-details').onclick=()=>root.querySelector('#startup-detail-panel').classList.toggle('hidden');root.querySelector('#startup-logs').onclick=async()=>{const feedback=root.querySelector('#startup-feedback');try{const path=await desktopInvoke('open_logs');feedback.textContent=`Opened ${path}`}catch(error){feedback.textContent=String(error)}};root.querySelector('#startup-exit').onclick=()=>desktopInvoke('exit_application')}
render=function(){if(state.startup?.status==='FAILED'){const root=document.querySelector('#app'),f=state.startup.failure||{};root.innerHTML=recoveryMarkup(f);bindRecovery(root,f);return}normalRender()};
const baseSettingsPage=settingsPage;
settingsPage=function(d){const services=Object.entries(d.health?.services||{}).map(([name,value])=>`<div><span>${name.replaceAll('_',' ')}</span><strong>${value.status}</strong></div>`).join('');const traySetting=desktopInvoke?`<label class="setting-toggle"><span><strong>Keep running in system tray when closed</strong><small>Closing the window hides it. Use the tray menu to reopen or exit.</small></span><input id="keep-running-in-tray" type="checkbox" ${state.keepRunningInTray?'checked':''}></label>`:`<p class="help">System tray behavior is available in the Windows desktop app.</p>`;const standards=`<section class="settings-grid standards-settings"><article class="panel"><h2>Application behavior</h2><p>Current view: <strong>${state.application.mode}</strong></p>${traySetting}<button id="run-setup-again">Run Setup Wizard Again</button><p class="help">Telemetry remains in place.</p></article><article class="panel"><h2>Local service status</h2><div class="service-health">${services}</div></article></section><article class="panel about-panel"><h2>${state.application.name}</h2><dl class="evidence"><div><dt>Version</dt><dd>${state.application.version}</dd></div><div><dt>Build type</dt><dd>${state.application.build_type}</dd></div><div><dt>Architecture</dt><dd>${state.application.architecture}</dd></div><div><dt>Repository</dt><dd>${state.application.repository}</dd></div><div><dt>License</dt><dd>${state.application.license}</dd></div><div><dt>Data directory</dt><dd>${state.application.data_directory}</dd></div></dl><p>Core analytics are local-first; paid API keys and cloud services are optional.</p></article>`;const dataManagement=`<p class="eyebrow export-title">DATA MANAGEMENT</p><button class="danger-button" id="clear-telemetry-data">Clear Telemetry Data</button><p class="help">Removes imported telemetry, import history, rejected-row examples, and telemetry-derived forecasts while preserving settings and configuration.</p>${!state.telemetryReset.open&&state.telemetryReset.message?`<div class="notice" id="telemetry-reset-message">${escapeHtml(state.telemetryReset.message)}</div>`:''}`;return baseSettingsPage(d).replace('<p class="eyebrow export-title">APPEARANCE</p>',dataManagement+'<p class="eyebrow export-title">APPEARANCE</p>').replace('<article class="panel audit-panel">',standards+'<article class="panel audit-panel">')+telemetryResetModal()};
document.addEventListener('click',async event=>{if(event.target?.id==='run-setup-again'){await api('/application/setup',{method:'DELETE'});state.application.first_run_complete=false;state.wizardStep=1;render()}});
document.addEventListener('change',async event=>{if(event.target?.id==='keep-running-in-tray'){const enabled=event.target.checked;event.target.disabled=true;try{await desktopInvoke('set_keep_running_in_tray',{enabled});state.keepRunningInTray=enabled}catch(error){event.target.checked=!enabled;alert(`Could not save system tray setting: ${error}`)}finally{event.target.disabled=false}}});
addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'overview';load()});applyTheme(localStorage.getItem('ts-theme')||'dark');checkDesktopStartup();
